CREATE TABLE schema_info(id INTEGER PRIMARY KEY CHECK(id=1), format TEXT NOT NULL CHECK(format='signdesk-plain-v1'), version INTEGER NOT NULL CHECK(version=1));
INSERT INTO schema_info VALUES(1,'signdesk-plain-v1',1);
CREATE TABLE platforms(id TEXT PRIMARY KEY NOT NULL, name TEXT NOT NULL, note TEXT NOT NULL DEFAULT '', enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN(0,1)), sort_order INTEGER NOT NULL DEFAULT 0, version INTEGER NOT NULL DEFAULT 1 CHECK(version>0));
CREATE TABLE accounts(id TEXT PRIMARY KEY NOT NULL, platform_id TEXT NOT NULL REFERENCES platforms(id) ON DELETE CASCADE, alias TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN(0,1)), sort_order INTEGER NOT NULL DEFAULT 0, version INTEGER NOT NULL DEFAULT 1 CHECK(version>0));
CREATE INDEX account_platform ON accounts(platform_id);
CREATE TABLE requests(id TEXT PRIMARY KEY NOT NULL, account_id TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE, name TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN(0,1)), current_revision INTEGER NOT NULL DEFAULT 1 CHECK(current_revision>0), rules_json TEXT NOT NULL, auth_paused INTEGER NOT NULL DEFAULT 0 CHECK(auth_paused IN(0,1)), sort_order INTEGER NOT NULL DEFAULT 0, version INTEGER NOT NULL DEFAULT 1 CHECK(version>0), safe_host TEXT NOT NULL DEFAULT '', method TEXT NOT NULL DEFAULT 'GET');
CREATE INDEX request_account ON requests(account_id);
CREATE TABLE request_revisions(request_id TEXT NOT NULL REFERENCES requests(id) ON DELETE CASCADE, revision INTEGER NOT NULL CHECK(revision>0), raw_curl TEXT NOT NULL, spec_json TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(request_id,revision));
CREATE TABLE request_templates(id TEXT PRIMARY KEY NOT NULL, platform_id TEXT NOT NULL REFERENCES platforms(id) ON DELETE CASCADE, name TEXT NOT NULL, rules_json TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1 CHECK(version>0));
CREATE INDEX request_templates_platform ON request_templates(platform_id);
CREATE TABLE platform_schedules(platform_id TEXT PRIMARY KEY NOT NULL REFERENCES platforms(id) ON DELETE CASCADE, revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0), enabled INTEGER NOT NULL DEFAULT 0 CHECK(enabled IN(0,1)), frequency TEXT NOT NULL DEFAULT 'daily' CHECK(frequency IN('daily','weekly')), weekdays_json TEXT NOT NULL DEFAULT '[1,2,3,4,5,6,7]', times_json TEXT NOT NULL DEFAULT '["09:00"]', timezone TEXT NOT NULL DEFAULT 'Asia/Shanghai' CHECK(timezone IN('Asia/Shanghai','UTC')), interval_seconds INTEGER NOT NULL DEFAULT 2 CHECK(interval_seconds BETWEEN 0 AND 60), catchup_minutes INTEGER NOT NULL DEFAULT 0 CHECK(catchup_minutes BETWEEN 0 AND 1440), skip_completed_daily INTEGER NOT NULL DEFAULT 1 CHECK(skip_completed_daily IN(0,1)), effective_from TEXT NOT NULL);
CREATE TABLE run_batches(id TEXT PRIMARY KEY NOT NULL, platform_id TEXT NOT NULL REFERENCES platforms(id) ON DELETE CASCADE, schedule_revision INTEGER NOT NULL, scheduled_at TEXT, business_date TEXT NOT NULL, timezone TEXT NOT NULL, source TEXT NOT NULL CHECK(source IN('auto','manual')), manual_key TEXT UNIQUE, force INTEGER NOT NULL DEFAULT 0 CHECK(force IN(0,1)), skip_completed_daily INTEGER NOT NULL DEFAULT 1 CHECK(skip_completed_daily IN(0,1)), interval_seconds INTEGER NOT NULL, expires_at TEXT, status TEXT NOT NULL DEFAULT 'queued' CHECK(status IN('queued','running','completed')), cancel_requested INTEGER NOT NULL DEFAULT 0 CHECK(cancel_requested IN(0,1)), created_at TEXT NOT NULL);
CREATE UNIQUE INDEX occurrence_once ON run_batches(platform_id,scheduled_at) WHERE source='auto';
CREATE INDEX batch_dispatch ON run_batches(status,created_at);
CREATE TABLE run_items(id TEXT PRIMARY KEY NOT NULL, batch_id TEXT NOT NULL REFERENCES run_batches(id) ON DELETE CASCADE, request_id TEXT NOT NULL REFERENCES requests(id) ON DELETE CASCADE, request_revision INTEGER NOT NULL, rules_json TEXT NOT NULL, ordinal INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'queued' CHECK(status IN('queued','running','success','already_done','expired','failed','unknown','skipped','cancelled')), http_status INTEGER, duration_ms INTEGER, safe_summary TEXT NOT NULL DEFAULT '', started_at TEXT, finished_at TEXT);
CREATE INDEX items_batch ON run_items(batch_id,ordinal);
CREATE INDEX items_request ON run_items(request_id,status);
CREATE UNIQUE INDEX request_active_once ON run_items(request_id) WHERE status IN('queued','running');
CREATE INDEX items_finished ON run_items(finished_at);
CREATE TABLE run_responses(run_id TEXT PRIMARY KEY NOT NULL REFERENCES run_items(id) ON DELETE CASCADE, body_bytes BLOB, content_type TEXT, charset TEXT, capture_state TEXT NOT NULL CHECK(capture_state IN('complete','partial','truncated','unavailable')), CHECK((capture_state='unavailable' AND body_bytes IS NULL) OR (capture_state<>'unavailable' AND body_bytes IS NOT NULL AND length(body_bytes)<=1048576)));
CREATE TABLE daily_completions(request_id TEXT NOT NULL REFERENCES requests(id) ON DELETE CASCADE, business_date TEXT NOT NULL, completed_run_id TEXT NOT NULL, PRIMARY KEY(request_id,business_date));
CREATE TABLE request_day_states(request_id TEXT NOT NULL REFERENCES requests(id) ON DELETE CASCADE, business_date TEXT NOT NULL, unknown_pending INTEGER NOT NULL DEFAULT 1 CHECK(unknown_pending IN(0,1)), PRIMARY KEY(request_id,business_date));
CREATE TABLE settings(id INTEGER PRIMARY KEY CHECK(id=1), paused INTEGER NOT NULL DEFAULT 0 CHECK(paused IN(0,1)), concurrency INTEGER NOT NULL DEFAULT 2 CHECK(concurrency BETWEEN 1 AND 8), timeout_seconds INTEGER NOT NULL DEFAULT 20 CHECK(timeout_seconds BETWEEN 1 AND 120), retention_days INTEGER NOT NULL DEFAULT 30 CHECK(retention_days BETWEEN 1 AND 365), version INTEGER NOT NULL DEFAULT 1 CHECK(version>0), proxy_mode TEXT NOT NULL DEFAULT 'system' CHECK(proxy_mode IN('system','direct','http','socks')), proxy_host TEXT NOT NULL DEFAULT '', proxy_port INTEGER NOT NULL DEFAULT 0);
INSERT INTO settings(id) VALUES(1);
